 practice(page,'tuning','guitar6','C#2 D#2 F#2 G#2 A#2 C#3');assert page.locator('.pilot-wheel button').count()==12;assert not page.locator('.wheel-center').count();page.wait_for_timeout(550);page.screenshot(path=str(OUT/'dual-wheel-v016.png'))
